insert into public.learning_levels (id, code, slug, name, cefr, description) values ('f2e3e98f-5cdd-55f6-99a4-8cf76086d8bb', 4, 'pte-preparation', 'PTE Preparation', 'B2', 'Academic vocabulary, complex sentences, essays, note-taking and all 22 PTE task types.');
