insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'l1-u1-first-steps', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'Unit 1: First steps', 'Letters and your first words: say hello and introduce yourself.', 1, '[{"id": "u11-t1", "type": "single_choice", "prompt": "Which of these is a vowel?", "options": ["k", "o", "s"], "answer": "o", "explanation": "The vowels are a, e, i, o and u."}, {"id": "u11-t2", "type": "single_choice", "prompt": "Which letter comes after \"g\"?", "options": ["f", "h", "j"], "answer": "h", "explanation": "The order is ... f, g, h, i, j ..."}, {"id": "u11-t3", "type": "single_choice", "prompt": "Which sentence uses capital letters correctly?", "options": ["i live in london.", "I live in London.", "I Live In london."], "answer": "I live in London.", "explanation": "Use a capital for \"I\", the first word, and names of places."}, {"id": "u11-t4", "type": "single_choice", "prompt": "It is 9 at night and you are going to bed. What do you say?", "options": ["Good morning", "Good night", "Hello"], "answer": "Good night", "explanation": "*Good night* is what we say late in the evening or before sleep."}, {"id": "u11-t5", "type": "single_choice", "prompt": "Complete: \"Hello, my ___ is Ana.\"", "options": ["name", "names", "named"], "answer": "name", "explanation": "We say *My name is ...* to introduce ourselves."}]'::jsonb, 'published');
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('d8107047-9780-5b15-b638-1478f05d58ca', 'l1-u2-words-and-sentences', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'Unit 2: Words and sentences', 'Kinds of words, one and many, and words like I, you and they.', 2, '[{"id": "u12-t1", "type": "single_choice", "prompt": "In \"The cat sleeps\", which word is a verb?", "options": ["The", "cat", "sleeps"], "answer": "sleeps", "explanation": "A verb is an action or state word: *sleeps*."}, {"id": "u12-t2", "type": "single_choice", "prompt": "What is the plural of \"box\"?", "options": ["boxs", "boxes", "boxies"], "answer": "boxes", "explanation": "Nouns ending in -x add -es: box → boxes."}, {"id": "u12-t3", "type": "single_choice", "prompt": "What is the plural of \"child\"?", "options": ["childs", "children", "childes"], "answer": "children", "explanation": "*Child* is irregular: one child, two children."}, {"id": "u12-t4", "type": "single_choice", "prompt": "Maria is my friend. ___ is from Spain.", "options": ["He", "She", "They"], "answer": "She", "explanation": "We use *she* for one woman or girl."}, {"id": "u12-t5", "type": "single_choice", "prompt": "Tom and I are students. ___ study English.", "options": ["We", "They", "You"], "answer": "We", "explanation": "*Tom and I* means *we*."}]'::jsonb, 'published');
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('2503eb05-3b66-544c-95d1-45606baa7208', 'the-alphabet', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'The English alphabet', 'Learn the 26 letters, capital and small letters, and the five vowel letters.', 1, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('bacf7994-da31-5bee-800e-3ce6ee72f37a', '2503eb05-3b66-544c-95d1-45606baa7208', 'learn', 1, '26 letters', 'English has **26 letters**.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('bb80d92c-f0c7-57aa-a380-b6789e41e925', '2503eb05-3b66-544c-95d1-45606baa7208', 'see', 2, 'Examples', '- **A a**: apple
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('1c7d4f82-3efd-5446-b3b9-53cf3808ff4a', '2503eb05-3b66-544c-95d1-45606baa7208', 'try', 3, 'Try it', 'Say the vowels out loud: **a, e, i, o, u**.', '[{"id": "alpha-try-1", "type": "single_choice", "prompt": "Which letter is a vowel?", "options": ["b", "e", "t"], "answer": "e", "hint": "There are five vowels: a, e, i, o, u.", "explanation": "**e** is one of the five vowel letters."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('bdff3461-b716-58d8-86f6-13d7ece5dd98', '2503eb05-3b66-544c-95d1-45606baa7208', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "alpha-check-1", "type": "single_choice", "prompt": "How many letters are in the English alphabet?", "options": ["24", "26", "28"], "answer": "26", "explanation": "The English alphabet has 26 letters."}, {"id": "alpha-check-2", "type": "single_choice", "prompt": "Which sentence uses capital letters correctly?", "options": ["my name is ali.", "My name is Ali.", "my Name is ali."], "answer": "My name is Ali.", "explanation": "Use a capital at the start of a sentence and for names."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('02dea9b0-e595-5fb1-8923-18ff38c82788', 'basic-vocabulary-greetings', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'Basic vocabulary: greetings', 'Say hello, say goodbye and introduce yourself.', 2, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('4bb7ba32-193c-5186-ad74-056e73002f35', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'learn', 1, 'Hello and goodbye', 'We **greet** people when we meet them.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('0c492850-27a8-543c-87e1-cce06e4b81b7', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'see', 2, 'A short conversation', '**Sam:** Hello! My name is Sam.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('93ab4981-a3d1-5dd5-a946-fc3241ae1685', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'try', 3, 'Try it', 'Introduce yourself: *Hello, my name is ...*', '[{"id": "greet-try-1", "type": "single_choice", "prompt": "It is 8 in the morning. What do you say?", "options": ["Good night", "Good morning", "Goodbye"], "answer": "Good morning", "hint": "Think about the time of day.", "explanation": "*Good morning* is a greeting for the morning."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('6e394bd0-f2b4-525e-a5a4-828f5b29c2d8', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "greet-check-1", "type": "single_choice", "prompt": "Someone says \"Nice to meet you.\" What is a good reply?", "options": ["Nice to meet you too.", "Goodbye.", "I am fine."], "answer": "Nice to meet you too.", "explanation": "We reply with the same words plus *too*."}, {"id": "greet-check-2", "type": "single_choice", "prompt": "Which word do we say when we leave?", "options": ["Hello", "Goodbye", "Hi"], "answer": "Goodbye", "explanation": "*Goodbye* is for leaving."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('19498871-224d-584a-bd4a-4fba1b8a125a', 'parts-of-speech', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'Parts of speech', 'Words have jobs: nouns, verbs, adjectives and more.', 3, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('532ba6d3-1bc8-5f07-9b6d-1052e86ac00d', '19498871-224d-584a-bd4a-4fba1b8a125a', 'learn', 1, 'Words have jobs', 'Every word has a **job** in a sentence.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('3d43bb19-84ef-5af9-b95b-015659e0c0fc', '19498871-224d-584a-bd4a-4fba1b8a125a', 'see', 2, 'Examples', '*The **happy** (adjective) **child** (noun) **runs** (verb) **quickly** (adverb).*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('edaa9c3f-0280-518c-a64d-d601f161a735', '19498871-224d-584a-bd4a-4fba1b8a125a', 'try', 3, 'Try it', 'Find the verb.', '[{"id": "pos-try-1", "type": "single_choice", "prompt": "In \"Birds sing\", which word is the verb?", "options": ["Birds", "sing"], "answer": "sing", "hint": "The verb is the action.", "explanation": "*sing* is the action, so it is the verb."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('19965829-ef60-5b53-a321-6d81007a791b', '19498871-224d-584a-bd4a-4fba1b8a125a', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "pos-check-1", "type": "single_choice", "prompt": "Which word is an adjective?", "options": ["table", "blue", "write"], "answer": "blue", "explanation": "*blue* describes a noun, so it is an adjective."}, {"id": "pos-check-2", "type": "single_choice", "prompt": "Which word is a noun?", "options": ["school", "quickly", "eat"], "answer": "school", "explanation": "*school* names a place, so it is a noun."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('fa28080c-61cc-5bad-94d4-529a605eafba', 'nouns-singular-plural', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'Nouns: one and many', 'Make plural nouns with -s and -es, and learn some special plurals.', 4, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('44249ada-1755-533c-a9b7-e29a50dd54fb', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'learn', 1, 'Singular and plural', '**Singular** means one. **Plural** means more than one.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('a9932a8a-5a32-5796-a90f-0bc4e3ec16f4', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'see', 2, 'Examples', '- one **cat**, two **cats**
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('50bec930-686e-5b97-a612-1caa8e00bf61', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'try', 3, 'Try it', 'Make the plural.', '[{"id": "noun-try-1", "type": "single_choice", "prompt": "One watch, two ...", "options": ["watchs", "watches"], "answer": "watches", "hint": "The word ends in -ch.", "explanation": "Nouns ending in -ch add -es: *watches*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('16aaa45b-055b-5544-a35a-1b2c74c43298', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "noun-check-1", "type": "single_choice", "prompt": "What is the plural of \"child\"?", "options": ["childs", "children", "childes"], "answer": "children", "explanation": "*child* has a special plural: *children*."}, {"id": "noun-check-2", "type": "single_choice", "prompt": "What is the plural of \"pen\"?", "options": ["pens", "penes", "pen"], "answer": "pens", "explanation": "Most nouns add -s."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'pronouns', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'Pronouns', 'Use I, you, he, she, it, we and they instead of repeating nouns.', 5, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('29eafd70-089d-5391-99eb-b11b8728961b', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'learn', 1, 'Words that replace nouns', 'A **pronoun** takes the place of a noun, so we do not repeat it.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('530ae39c-bb29-53b5-aefe-1826785f1d11', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'see', 2, 'Examples', '*Anna is a doctor. **She** works in a hospital.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('4aab0ab1-7b9d-5bd1-9f2e-2ad5cc90cf90', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'try', 3, 'Try it', 'Choose the pronoun.', '[{"id": "pron-try-1", "type": "single_choice", "prompt": "Tom is tall. ... plays basketball.", "options": ["She", "He", "They"], "answer": "He", "hint": "Tom is one man.", "explanation": "For one man we use *he*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('3504e903-c736-52c2-ba2c-41c080c5e0be', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "pron-check-1", "type": "single_choice", "prompt": "The books are new. ... are on the table.", "options": ["It", "They", "We"], "answer": "They", "explanation": "For many things we use *they*."}, {"id": "pron-check-2", "type": "single_choice", "prompt": "My sister and I are students. ... study English.", "options": ["We", "They", "She"], "answer": "We", "explanation": "*My sister and I* includes me, so we use *we*."}]'::jsonb);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('980cfa9c-04d2-5213-b25b-9c2ffdd77f6d', 'sst-0001', 'f7f6fdbd-4e43-52be-9694-1e49b80c2f7e', 'intermediate', 'You will hear a short report. Write a summary for a fellow student who was not present. You should write 50-70 words.', '{"audio_script": "Many people throw away food that is still safe to eat because they misunderstand date labels. A ''best before'' date is about quality, not safety, so food is often fine after that date. A ''use by'' date, however, is about safety and should be followed. Clearer labels and simple public information could reduce household food waste significantly."}'::jsonb, '{"model_answer": "The speaker explained that much food waste happens because people confuse date labels. ''Best before'' refers to quality, so food can often be eaten after this date, while ''use by'' is a safety limit that must be respected. The speaker suggested that clearer labelling and better public information could greatly reduce the amount of food households throw away."}'::jsonb, 'Include the problem, the difference between the two labels and the suggested solution.', 'Summarize a short talk in 50-70 words.', array['Content', 'Form', 'Grammar', 'Vocabulary', 'Spelling']::text[], array['food wasted due to label confusion', 'best before = quality', 'use by = safety', 'clearer labels reduce waste']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0c544db4-2d46-5fe2-908f-3e81429ae100', 'sst-0002', 'f7f6fdbd-4e43-52be-9694-1e49b80c2f7e', 'advanced', 'You will hear a short report. Write a summary for a fellow student who was not present. You should write 50-70 words.', '{"audio_script": "Green roofs, which are roofs covered with plants, are becoming popular in large cities. They absorb rainwater, which reduces flooding, and they keep buildings cooler in summer. They also provide habitats for insects. The main barriers are the cost of installation and the need to check that older buildings can support the extra weight."}'::jsonb, '{"model_answer": "The talk described green roofs, which are planted roofs increasingly used in cities. They help by absorbing rain to reduce flooding, cooling buildings in hot weather and supporting insect life. However, they can be expensive to install, and older buildings must be checked to make sure they are strong enough to carry the added weight of soil and plants."}'::jsonb, 'Give the definition, the benefits and the barriers.', 'Summarize benefits and limitations from a talk.', array['Content', 'Form', 'Grammar', 'Vocabulary', 'Spelling']::text[], array['green roofs = planted roofs', 'reduce flooding, cool buildings, insect habitat', 'cost and weight barriers']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'lmcm-0001', '98cdddc4-46fd-53a3-aa5d-862c3528a2fe', 'intermediate', 'Listen to the recording and answer the question by selecting all the correct responses. You will need to select more than one response.', '{"audio_script": "Our study group found that reading aloud helped us remember new words, and testing each other every Friday showed us which topics we still did not understand. Highlighting the textbook, though, did not seem to make much difference.", "question": "Which study methods did the speaker find useful?"}'::jsonb, '{"correct": ["A", "B"]}'::jsonb, 'Reading aloud and Friday tests helped. Highlighting "did not seem to make much difference". Videos were not mentioned.', 'Track which ideas the speaker supports or rejects.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e383fddb-d9a1-50cc-922e-69815c81aeff', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'A', 'Reading aloud', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('849358b2-f150-5d4b-938c-36dca8e41f18', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'B', 'Weekly testing of each other', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('faa186f5-61bb-5aa2-813d-db0050ce7ae1', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'C', 'Highlighting the textbook', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('9ef36130-6d84-5666-b9e0-12d3b11b96ea', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'D', 'Watching videos', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'lmcm-0002', '98cdddc4-46fd-53a3-aa5d-862c3528a2fe', 'advanced', 'Listen to the recording and answer the question by selecting all the correct responses. You will need to select more than one response.', '{"audio_script": "When the city introduced free buses for students, two things happened. Car traffic near schools fell, and attendance in the poorer districts rose. Bus crowding at peak times, however, became a new challenge.", "question": "What results of the free bus scheme are mentioned?"}'::jsonb, '{"correct": ["A", "B", "C"]}'::jsonb, 'The speaker mentions all three results A, B and C. Adult prices are not mentioned.', 'Catch positive and negative outcomes.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('36be7cca-f457-5a80-b6ec-f7c2df047a85', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'A', 'Less car traffic near schools', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('08cd8d4e-956b-5a98-a3c7-e9f5449fefcf', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'B', 'Higher attendance in poorer areas', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('34f78a61-ec35-520d-b8d7-a0b2ebfb91ed', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'C', 'Crowded buses at busy times', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('8053e63f-9cc1-5faf-b198-bfd78711eda1', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'D', 'Lower bus ticket prices for adults', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('16df8aef-d6bb-5188-89fa-724882ff4eec', 'lfib-0001', 'f0bf404a-0ff4-565e-a293-9130eb80ecd8', 'beginner', 'You will hear a recording. Type the missing words in each blank.', '{"audio_script": "Please bring your student card and a pencil to the exam room.", "text": "Please bring your student {{1}} and a {{2}} to the exam room."}'::jsonb, '{"blanks": {"1": "card", "2": "pencil"}}'::jsonb, 'Listen for the exact words and check the spelling.', 'Write exact words heard in a sentence.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1dcee511-c566-50c1-9725-4cceae95b9f4', 'lfib-0002', 'f0bf404a-0ff4-565e-a293-9130eb80ecd8', 'intermediate', 'You will hear a recording. Type the missing words in each blank.', '{"audio_script": "The research team collected data from schools in three different regions over a period of two years.", "text": "The research team collected {{1}} from schools in three different {{2}} over a period of two years."}'::jsonb, '{"blanks": {"1": "data", "2": "regions"}}'::jsonb, '"regions" is plural because of "three different".', 'Use grammar clues to check what you heard.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('6dc2c902-8ede-5643-bc6b-a657deab0b95', 'hcs-0001', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'intermediate', 'You will hear a recording. Click on the paragraph that best relates to the recording.', '{"audio_script": "Many young people now choose to rent rather than buy homes. Rising house prices are one reason, but surveys show that some also value the freedom to move for work."}'::jsonb, '{"correct": ["B"]}'::jsonb, 'B includes both reasons: prices and freedom to move.', 'Choose the summary that includes all main points.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('4f8fdeca-4f7e-51a0-b7cb-fd5893297eef', '6dc2c902-8ede-5643-bc6b-a657deab0b95', 'A', 'Young people rent mainly because they dislike owning property.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3344c555-84f5-537a-93f0-0ef350676091', '6dc2c902-8ede-5643-bc6b-a657deab0b95', 'B', 'Young people increasingly rent because of high prices and a wish for flexibility.', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('404b1098-85b8-5b49-978e-83b6b58d8634', '6dc2c902-8ede-5643-bc6b-a657deab0b95', 'C', 'House prices are falling, so fewer young people buy homes.', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1489e580-3946-5fbf-bb18-d062e7bbf653', 'hcs-0002', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'advanced', 'You will hear a recording. Click on the paragraph that best relates to the recording.', '{"audio_script": "Electric cars produce no exhaust while driving, but their batteries require mining for materials such as lithium. Their overall environmental benefit depends largely on how the electricity used to charge them is produced."}'::jsonb, '{"correct": ["C"]}'::jsonb, 'C keeps the balanced view of the speaker. A and B are too extreme.', 'Avoid summaries that are too extreme.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('09e780cd-d1ad-5f78-b3be-9448e253bc9c', '1489e580-3946-5fbf-bb18-d062e7bbf653', 'A', 'Electric cars are always better for the environment than petrol cars.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e3bf8d8f-dc23-53e7-a961-c34697d49adb', '1489e580-3946-5fbf-bb18-d062e7bbf653', 'B', 'Battery mining makes electric cars worse than petrol cars.', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('cc8ed646-b6ad-5e3c-a0a8-45036b9809b8', '1489e580-3946-5fbf-bb18-d062e7bbf653', 'C', 'Electric cars have no exhaust, but their real benefit depends on battery materials and electricity sources.', true, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'lmcs-0001', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'beginner', 'Listen to the recording and answer the multiple-choice question by selecting the correct response. Only one response is correct.', '{"audio_script": "The college gym will be closed next Monday for cleaning. It will open again on Tuesday at seven in the morning.", "question": "When will the gym open again?"}'::jsonb, '{"correct": ["B"]}'::jsonb, '"open again on Tuesday at seven in the morning".', 'Catch days and times.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('47a98f35-4cc3-5d6e-a23a-d7b7ed08b08b', '357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'A', 'Monday at 7 am', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('cefa0a46-e533-511a-b7aa-80666089ff6d', '357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'B', 'Tuesday at 7 am', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('2e529c7c-108d-508d-a70c-f3ebb92f3b89', '357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'C', 'Tuesday at 7 pm', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'lmcs-0002', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'intermediate', 'Listen to the recording and answer the multiple-choice question by selecting the correct response. Only one response is correct.', '{"audio_script": "I used to think that multitasking saved time. But after tracking my work for a month, I realised I finished tasks faster when I focused on one thing at a time.", "question": "What is the speaker''s conclusion?"}'::jsonb, '{"correct": ["B"]}'::jsonb, '"used to think" shows an old belief. The conclusion is that single-tasking was faster.', 'Recognise a change of opinion.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('a0f6c074-d3a6-5c8d-9a40-fec347d7c676', '0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'A', 'Multitasking saves time.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('ca60814c-1c53-5439-9821-936007c7bb8a', '0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'B', 'Focusing on one task is more efficient.', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e3c397b6-8ee5-51de-a525-e9a6feb148c8', '0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'C', 'Tracking work wastes time.', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a7e49192-cb17-599e-8c85-8776356d85fa', 'smw-0001', 'fd9c8418-e1bd-5d16-b156-36ed58e7f9ea', 'beginner', 'You will hear a recording. At the end of the recording the last word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '{"audio_script": "It was raining heavily all morning, so we decided to stay [BEEP]."}'::jsonb, '{"correct": ["A"]}'::jsonb, 'Heavy rain is a reason to stay inside.', 'Predict an ending from cause and effect.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('dd644ddf-f8c2-5f38-86fe-5672e6353305', 'a7e49192-cb17-599e-8c85-8776356d85fa', 'A', 'inside', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('ebeecc19-5922-5df5-8b0a-7e5194d1cfab', 'a7e49192-cb17-599e-8c85-8776356d85fa', 'B', 'outside', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('35e23022-9d25-5734-802d-550e9a2a496b', 'a7e49192-cb17-599e-8c85-8776356d85fa', 'C', 'awake', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('e6d1dc08-abb6-5b37-abec-5fb759c01873', 'smw-0002', 'fd9c8418-e1bd-5d16-b156-36ed58e7f9ea', 'intermediate', 'You will hear a recording. At the end of the recording the last word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '{"audio_script": "The first experiment failed, and so did the second. However, the team did not give up, and the third attempt was finally a [BEEP]."}'::jsonb, '{"correct": ["B"]}'::jsonb, '"However" and "finally" show a positive change: success.', 'Use contrast words to predict meaning.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('83d3dae6-366e-5e18-b941-620418b8ec87', 'e6d1dc08-abb6-5b37-abec-5fb759c01873', 'A', 'disaster', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('66bdd551-1c5c-519b-bf28-8d268027a15d', 'e6d1dc08-abb6-5b37-abec-5fb759c01873', 'B', 'success', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('da093a23-f964-5869-beb1-787b2a6539e5', 'e6d1dc08-abb6-5b37-abec-5fb759c01873', 'C', 'mistake', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('4be9ac65-7a89-5548-bc5d-534c47e036f0', 'hiw-0001', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'beginner', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', '{"audio_script": "Our class visited the science museum on Thursday and saw a large model of the planets.", "transcript": "Our class visited the history museum on Thursday and saw a small model of the planets."}'::jsonb, '{"incorrect_words": [{"index": 4, "word": "history", "spoken": "science"}, {"index": 10, "word": "small", "spoken": "large"}]}'::jsonb, 'The speaker said "science" and "large".', 'Follow a transcript while listening.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('53c94e83-dfa7-538a-bff2-1960096b9d04', 'hiw-0002', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'intermediate', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', '{"audio_script": "The survey found that most employees preferred flexible hours to a higher salary.", "transcript": "The survey showed that most employees preferred flexible days to a higher salary."}'::jsonb, '{"incorrect_words": [{"index": 2, "word": "showed", "spoken": "found"}, {"index": 8, "word": "days", "spoken": "hours"}]}'::jsonb, 'The speaker said "found" and "hours".', 'Notice small changes in meaning.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3bc936f4-8162-5200-bb45-24a66e81027e', 'wfd-0001', 'c4f6e94e-f068-5719-b756-005c6e22e8fa', 'beginner', 'You will hear a sentence. Type the sentence in the box below exactly as you hear it.', '{"audio_script": "The lecture will start in the main hall."}'::jsonb, '{"reference_text": "The lecture will start in the main hall."}'::jsonb, 'Write every word, and check small words like "the" and "in".', 'Write a short sentence accurately.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d6c45e86-1888-5bad-a845-e3fd87b13f8a', 'wfd-0002', 'c4f6e94e-f068-5719-b756-005c6e22e8fa', 'intermediate', 'You will hear a sentence. Type the sentence in the box below exactly as you hear it.', '{"audio_script": "Applications must be submitted before the end of the month."}'::jsonb, '{"reference_text": "Applications must be submitted before the end of the month."}'::jsonb, 'Check the plural "Applications" and the passive "be submitted".', 'Write a sentence with a passive verb.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('30c5e482-7ecb-5a77-a237-bb23a3b00e84', 'rwfib-0001', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.', '{"text": "Regular exercise is good for both the body and the {{1}}. People who walk every day often {{2}} better at night.", "blanks": {"1": ["mind", "minds", "mindful"], "2": ["sleep", "sleeping", "slept"]}}'::jsonb, '{"blanks": {"1": "mind", "2": "sleep"}}'::jsonb, '"the body and the mind" needs a singular noun. After "often" in the present simple, we use the base verb "sleep".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('07320d69-3094-5621-8c41-6c8e0e14c1ae', 'rwfib-0002', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.', '{"text": "The museum''s new exhibition has {{1}} large crowds since it opened. Visitors are especially {{2}} in the section on ancient maps.", "blanks": {"1": ["attracted", "attractive", "attraction"], "2": ["interested", "interesting", "interest"]}}'::jsonb, '{"blanks": {"1": "attracted", "2": "interested"}}'::jsonb, '"has ... since" needs a past participle: "attracted". People feel "interested"; things are "interesting".', 'Use word forms (verb, adjective, noun) correctly.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d2005a3b-a801-50a6-87d0-42f6f3a800aa', 'rmcm-0001', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text and answer the question by selecting all the correct responses. More than one response is correct.', '{"passage": "Coral reefs cover a very small part of the ocean floor, yet they are home to about a quarter of all known marine species. Reefs also protect coastlines by breaking up strong waves. Rising sea temperatures cause corals to lose the algae that feed them, a process known as bleaching.", "question": "According to the text, which of the following are true about coral reefs?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'A matches "a quarter of all known marine species". C matches "breaking up strong waves". The text says reefs cover a small part of the floor and bleaching comes from rising temperatures.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('07a4514c-e738-57e0-b520-03862848b8b1', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'A', 'They support a large share of marine species.', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('34c5a5e9-f21b-5641-9a3c-3c2a5ff6ff3c', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'B', 'They cover most of the ocean floor.', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('f84eb6cb-4f9a-511c-acd9-ba833f34afdd', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'C', 'They reduce the force of waves on coasts.', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3ae83b9c-87cf-58fd-90b5-771ee1476d7e', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'D', 'Bleaching is caused by cold water.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('4dea0915-a43e-5f82-84bf-eddc720794dd', 'rmcm-0002', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text and answer the question by selecting all the correct responses. More than one response is correct.', '{"passage": "Night shifts can disturb the body''s internal clock. Workers on long-term night schedules report more digestive problems and poorer sleep quality. Some employers now offer brighter lighting during shifts and blackout blinds for daytime rest, which appear to reduce these effects.", "question": "Which measures does the writer mention to reduce the effects of night work?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'Only lighting and blackout blinds are mentioned as measures.', 'Separate stated measures from ideas that are not in the text.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('64ff5409-b34f-52f9-a230-d80f53401329', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'A', 'Brighter lighting at work', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('dcb833ac-3f70-5d78-9873-bd6aa4f418fb', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'B', 'Shorter shifts', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('554b4178-8ec8-5898-9bad-148b21a8c598', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'C', 'Blackout blinds for sleeping in the day', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('6f6c1281-06d9-5881-85d0-f0698687819f', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'D', 'Special diets', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('732d1e83-ee96-5d63-91d4-8dc05f702b61', 'rop-0001', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The text boxes below have been placed in a random order. Restore the original order.', '{"paragraphs": [{"id": "p1", "text": "First, fill the kettle with fresh water and switch it on."}, {"id": "p2", "text": "Finally, add milk or sugar if you like, and enjoy your tea."}, {"id": "p3", "text": "While the water heats, put a tea bag into a cup."}, {"id": "p4", "text": "When the water boils, pour it over the tea bag and wait three minutes."}]}'::jsonb, '{"order": ["p1", "p3", "p4", "p2"]}'::jsonb, 'Follow the time words: First, While, When, Finally.', 'Use sequence words to order a process.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('156adfac-8b84-5daa-93c7-77a394bcbd53', 'rop-0002', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The text boxes below have been placed in a random order. Restore the original order.', '{"paragraphs": [{"id": "p1", "text": "As a result, the town decided to build a new cycle lane along the river."}, {"id": "p2", "text": "Traffic in the town centre had become a serious problem by 2020."}, {"id": "p3", "text": "A survey showed that many residents would cycle if they felt safer on the roads."}, {"id": "p4", "text": "Since the lane opened, the number of cyclists has doubled."}]}'::jsonb, '{"order": ["p2", "p3", "p1", "p4"]}'::jsonb, 'Problem, then evidence, then decision ("As a result"), then outcome ("Since").', 'Order a problem-solution text using linking words.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('bc8af956-5a7d-5536-a64c-efd187515308', 'rfib-0001', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'In the text below some words are missing. Drag words from the box below to the appropriate place in the text.', '{"text": "Water {{1}} at 100 degrees Celsius at sea level. When it gets very cold, it {{2}} into ice.", "word_bank": ["boils", "turns", "grows", "melts"]}'::jsonb, '{"blanks": {"1": "boils", "2": "turns"}}'::jsonb, 'Water boils at 100°C. It "turns into" ice when it freezes. "melts" is the opposite process.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3b497e9b-061a-5c01-b8ff-d590b89af68c', 'rfib-0002', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'In the text below some words are missing. Drag words from the box below to the appropriate place in the text.', '{"text": "The company plans to {{1}} its office in March. Staff will be able to work from home during the {{2}} period.", "word_bank": ["renovate", "transition", "decorate", "pause"]}'::jsonb, '{"blanks": {"1": "renovate", "2": "transition"}}'::jsonb, '"renovate its office" is a natural collocation. "transition period" is a fixed phrase.', 'Recognise common academic collocations.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('46fcce68-9c69-55e3-ad8b-592732463f73', 'rmcs-0001', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text and answer the multiple-choice question by selecting the correct response. Only one response is correct.', '{"passage": "The town market opens every Saturday from 8 am to 1 pm. Most stalls sell fresh fruit and vegetables, but there are also stalls selling bread and handmade soap.", "question": "What is the main thing sold at the market?"}'::jsonb, '{"correct": ["B"]}'::jsonb, '"Most stalls" sell fruit and vegetables. Bread and soap are "also" sold, so they are not the main thing.', 'Identify the main idea versus extra details.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('4923ff12-c273-5627-9b82-38e02139f81f', '46fcce68-9c69-55e3-ad8b-592732463f73', 'A', 'Bread', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e1b77dde-e4a2-5d6f-8be2-9adcc066263f', '46fcce68-9c69-55e3-ad8b-592732463f73', 'B', 'Fresh fruit and vegetables', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('b6e4dd89-8f36-5758-9b45-75bf5649c087', '46fcce68-9c69-55e3-ad8b-592732463f73', 'C', 'Handmade soap', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9418db97-0971-52f4-9984-f14a8d308ca3', 'rmcs-0002', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text and answer the multiple-choice question by selecting the correct response. Only one response is correct.', '{"passage": "While online courses offer flexibility, completion rates remain low. Studies suggest that learners who set a fixed weekly study time and join a discussion group are much more likely to finish.", "question": "What is the writer''s main point?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'The text says completion is low, but fixed times and groups help learners finish.', 'Find the writer''s main point in a short argument.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('c434373f-93a9-5a8a-a80b-a7a3a4bfc9b8', '9418db97-0971-52f4-9984-f14a8d308ca3', 'A', 'Online courses are not flexible.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3170b4db-cf9a-551c-a57a-a27366e61576', '9418db97-0971-52f4-9984-f14a8d308ca3', 'B', 'Structure and social support help learners finish online courses.', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('5bb36908-75e2-56ce-8893-c3dba8fd2967', '9418db97-0971-52f4-9984-f14a8d308ca3', 'C', 'Discussion groups are more useful than courses.', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d1a19b9b-0b16-5ba1-928a-f3fb960fac1f', 'ra-0001', 'a3ae1a47-54fa-53b1-a663-dbb4a3264362', 'beginner', 'Look at the text below. Read it aloud as naturally and clearly as possible.', '{"text": "Many cities now plant trees along busy roads. The trees give shade in summer, reduce noise from traffic and make the streets more pleasant for people who walk to work."}'::jsonb, '{"reference_text": "Many cities now plant trees along busy roads. The trees give shade in summer, reduce noise from traffic and make the streets more pleasant for people who walk to work."}'::jsonb, 'Read in phrases, not word by word. Pause briefly at commas and full stops.', 'Read a short factual text aloud with clear pronunciation and natural phrasing.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0572d759-cf7f-5527-a087-211b3705d256', 'ra-0002', 'a3ae1a47-54fa-53b1-a663-dbb4a3264362', 'intermediate', 'Look at the text below. Read it aloud as naturally and clearly as possible.', '{"text": "Researchers studying sleep have found that teenagers naturally fall asleep later than adults. As a result, some schools have moved their start time to later in the morning, and early reports suggest that attendance has improved."}'::jsonb, '{"reference_text": "Researchers studying sleep have found that teenagers naturally fall asleep later than adults. As a result, some schools have moved their start time to later in the morning, and early reports suggest that attendance has improved."}'::jsonb, 'Stress the content words (researchers, teenagers, later, attendance) and keep a steady pace.', 'Read a longer academic text with correct word stress.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('89b1e8a9-4743-58ee-beca-cf2bb3c7c2d7', 'rs-0001', '7c6899f2-cb0f-51b5-918e-5b3a66defe02', 'beginner', 'You will hear a sentence. Please repeat the sentence exactly as you hear it.', '{"audio_script": "The library closes at six on Fridays."}'::jsonb, '{"reference_text": "The library closes at six on Fridays."}'::jsonb, 'Listen for meaning, not single words. Remember the sentence as one idea.', 'Hold a short sentence in memory and repeat it accurately.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('6f1134e4-325c-5e6a-87a3-92692ef9f309', 'rs-0002', '7c6899f2-cb0f-51b5-918e-5b3a66defe02', 'intermediate', 'You will hear a sentence. Please repeat the sentence exactly as you hear it.', '{"audio_script": "Students who submit their assignments late must speak to the course coordinator."}'::jsonb, '{"reference_text": "Students who submit their assignments late must speak to the course coordinator."}'::jsonb, 'Break the sentence into two chunks: who it is about, and what they must do.', 'Repeat a sentence with a relative clause.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('03da1430-4de7-5350-8932-0aa762f68262', 'di-0001', 'f0be0416-0643-5200-8465-6eb775a49e76', 'beginner', 'Look at the image below. In 25 seconds, prepare to describe in detail what the image is showing.', '{"image": {"kind": "bar_chart", "title": "Books borrowed per month at a town library", "data": [{"label": "January", "value": 420}, {"label": "February", "value": 380}, {"label": "March", "value": 510}, {"label": "April", "value": 600}]}}'::jsonb, '{"model_answer": "The bar chart shows how many books a town library lent each month from January to April. Borrowing dipped slightly from 420 in January to 380 in February, then rose steadily to a peak of 600 in April. Overall, the library became busier during spring."}'::jsonb, 'Say what the image is, give the highest and lowest values, describe the trend, then give a conclusion.', 'Describe a simple bar chart using trend language.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['library books per month', 'lowest in February (380)', 'highest in April (600)', 'overall upward trend']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('73724c3a-0c82-5016-88c6-354efafedfef', 'di-0002', 'f0be0416-0643-5200-8465-6eb775a49e76', 'intermediate', 'Look at the image below. In 25 seconds, prepare to describe in detail what the image is showing.', '{"image": {"kind": "pie_chart", "title": "How students travel to a college", "data": [{"label": "Bus", "value": 40}, {"label": "Walk", "value": 25}, {"label": "Bicycle", "value": 20}, {"label": "Car", "value": 15}]}}'::jsonb, '{"model_answer": "The pie chart shows how students get to a college. The bus is the most common choice at forty percent, followed by walking at a quarter. Twenty percent cycle, and only fifteen percent travel by car. In short, most students use low-cost or active travel."}'::jsonb, 'Compare the parts: biggest, smallest and any similar values.', 'Describe proportions in a pie chart.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['student travel to college', 'bus largest (40%)', 'car smallest (15%)', 'walking and cycling together 45%']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('5fee338b-ed83-5fc1-824d-8c51d63dc532', 'rl-0001', '4d460dfa-9371-56a2-b754-40d96c6ad99e', 'intermediate', 'You will hear a lecture. After listening, you will have 10 seconds to prepare, then retell what you have just heard in your own words.', '{"audio_script": "Today I want to talk about honeybees and why farmers care about them. Bees carry pollen from flower to flower, and this allows many fruit and vegetable plants to produce food. In some regions, bee numbers have fallen because of disease, loss of wild flowers and certain pesticides. Some farmers now plant strips of wild flowers beside their fields to give bees food and shelter."}'::jsonb, '{"model_answer": "The lecture explained that bees are important to farmers because they pollinate many food crops. Bee numbers have dropped in some places because of disease, fewer wild flowers and pesticides. To help, some farmers grow wild flower strips next to their fields."}'::jsonb, 'Note the topic, two or three main points and the conclusion. Use your own words.', 'Retell the main ideas of a short lecture.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['bees pollinate crops', 'bee numbers falling', 'causes: disease, fewer flowers, pesticides', 'farmers plant wild flower strips']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7ff218f2-772c-5ec2-9a21-838f150487d9', 'rl-0002', '4d460dfa-9371-56a2-b754-40d96c6ad99e', 'advanced', 'You will hear a lecture. After listening, you will have 10 seconds to prepare, then retell what you have just heard in your own words.', '{"audio_script": "The idea of a four-day working week has moved from theory to real trials. In several trials, staff kept the same pay but worked one day less. Many companies reported similar output, while employees described less stress and better sleep. Critics argue that the results may not apply to jobs such as hospital care, where someone must always be present."}'::jsonb, '{"model_answer": "The speaker discussed trials of a four-day working week with no cut in pay. Many firms kept the same output and workers reported lower stress and better sleep. However, critics say the model may not suit jobs like hospital work that need constant cover."}'::jsonb, 'Include the contrast at the end: the benefits and the criticism.', 'Retell a lecture that includes a counter-argument.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['four-day week trials', 'same pay, one day less', 'similar output, less stress', 'may not suit jobs needing constant cover']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d2672795-e931-53dc-a18d-5ad0db18ad0a', 'asq-0001', 'f26d9c2f-752a-5177-be36-02d0006010a2', 'beginner', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', '{"audio_script": "What do we call the meal people usually eat in the morning?"}'::jsonb, '{"accepted": ["breakfast"]}'::jsonb, 'The morning meal is breakfast.', 'Answer an everyday knowledge question with one word.', array['Vocabulary']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ea5c076d-3472-53d1-9f6a-e602b2638bec', 'asq-0002', 'f26d9c2f-752a-5177-be36-02d0006010a2', 'beginner', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', '{"audio_script": "How many sides does a triangle have?"}'::jsonb, '{"accepted": ["three", "3"]}'::jsonb, 'A triangle has three sides.', 'Answer a basic maths question quickly.', array['Vocabulary']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('784c7b11-4dbc-5f37-912d-1fb489c69314', 'sgd-0001', '71a77aef-e49f-5acc-a085-deaa6bf6488d', 'intermediate', 'You will hear a group discussion. Summarize the main points of the discussion in your own words.', '{"speakers": ["Amira", "Ben", "Chen"], "audio_script": [{"speaker": "Amira", "text": "I think the university should keep the library open all night during exams."}, {"speaker": "Ben", "text": "That sounds good, but who pays for the extra staff and security?"}, {"speaker": "Chen", "text": "Maybe we could open just one floor overnight, with self-service machines, to keep costs down."}]}'::jsonb, '{"model_answer": "The students discussed opening the library all night during exams. Amira supported the idea, Ben worried about the cost of staff and security, and Chen suggested a compromise of opening one self-service floor overnight."}'::jsonb, 'Name each speaker''s position and the final suggestion.', 'Summarize different opinions in a short discussion.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['proposal: open library overnight in exams', 'concern: cost of staff and security', 'compromise: one self-service floor']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c9b5e3c3-f80a-5721-ba09-c671806507e6', 'sgd-0002', '71a77aef-e49f-5acc-a085-deaa6bf6488d', 'advanced', 'You will hear a group discussion. Summarize the main points of the discussion in your own words.', '{"speakers": ["Dana", "Eli", "Farah"], "audio_script": [{"speaker": "Dana", "text": "Our group project should use online meetings, because we all live far apart."}, {"speaker": "Eli", "text": "Online is convenient, but last time people turned their cameras off and nobody spoke."}, {"speaker": "Farah", "text": "Then let''s meet online each week but set a short agenda and give everyone a task to report on."}]}'::jsonb, '{"model_answer": "The group talked about how to meet for their project. Dana preferred online meetings because members live far apart. Eli agreed they are convenient but said people did not take part last time. Farah proposed weekly online meetings with an agenda and a task for each person."}'::jsonb, 'Show how the ideas build on each other to reach a solution.', 'Summarize a discussion that reaches a solution.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['online meetings because of distance', 'problem: low participation', 'solution: agenda and tasks for everyone']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('5a29b083-8a4c-5dd5-8adc-377fa199303f', 'rts-0001', 'd74a6ad6-8f3a-5163-9210-faac5c28e9e4', 'beginner', 'Listen to and read a description of a situation. You will have 20 seconds to think about your answer. Then you will hear a beep and have 40 seconds to answer the question.', '{"situation": "You borrowed a classmate''s notes for a week, but you spilled coffee on one page. You are going to return the notes now. What do you say to your classmate?"}'::jsonb, '{"model_answer": "Hi Jamie, thank you so much for lending me your notes. I''m really sorry, but I spilled some coffee on page four. I''ve copied that page out neatly for you, and I''m happy to buy you a coffee to say sorry."}'::jsonb, 'Thank the person, explain the problem honestly, apologise and offer a solution.', 'Apologise politely and offer a solution.', array['Appropriacy', 'Oral fluency', 'Pronunciation']::text[], array['thank', 'explain the problem', 'apologise', 'offer a fix']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a240ced8-2d59-59e2-abed-fbddea0465f7', 'rts-0002', 'd74a6ad6-8f3a-5163-9210-faac5c28e9e4', 'intermediate', 'Listen to and read a description of a situation. You will have 20 seconds to think about your answer. Then you will hear a beep and have 40 seconds to answer the question.', '{"situation": "Your manager has asked you to work this Saturday, but you have already booked a train ticket to visit your family. What do you say to your manager?"}'::jsonb, '{"model_answer": "Thanks for thinking of me for Saturday. Unfortunately, I''ve already booked a train to visit my family that day, so I can''t come in. Could I help by staying late on Thursday or Friday, or by finishing part of the work from home before I leave?"}'::jsonb, 'Decline politely, give a reason and offer an alternative.', 'Decline a request politely in a work setting.', array['Appropriacy', 'Oral fluency', 'Pronunciation']::text[], array['polite refusal', 'clear reason', 'alternative offer']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1366d92b-83a3-5323-9e16-36f5c61d251d', 'swt-0001', '592287fc-2723-5ab2-812f-f18d75a3190f', 'intermediate', 'Read the passage below and summarize it using one sentence. You have 10 minutes. Your response should be between 5 and 75 words.', '{"passage": "Community gardens are spaces where neighbours grow vegetables and flowers together on shared land. Supporters say they improve access to fresh food, especially in areas with few shops. They also bring people of different ages and backgrounds together, which can reduce loneliness. However, gardens often depend on volunteers and temporary agreements with landowners, so many struggle to survive for more than a few years."}'::jsonb, '{"model_answer": "Community gardens improve access to fresh food and bring neighbours together, but their reliance on volunteers and temporary land agreements often makes them hard to sustain."}'::jsonb, 'Combine the main benefit and the main problem in one sentence with a linking word such as "but".', 'Write a one-sentence summary that links ideas.', array['Content', 'Form', 'Grammar', 'Vocabulary']::text[], array['fresh food access', 'bring people together', 'depend on volunteers and temporary land']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('650de8f8-7a34-50dd-af02-4003654b217f', 'swt-0002', '592287fc-2723-5ab2-812f-f18d75a3190f', 'advanced', 'Read the passage below and summarize it using one sentence. You have 10 minutes. Your response should be between 5 and 75 words.', '{"passage": "Electric scooters for hire have spread quickly through many cities. They offer a cheap and fast way to make short trips without a car. Yet city councils have raised concerns about riders using pavements, scooters left blocking paths, and injuries among inexperienced users. In response, some cities now require parking zones, speed limits in busy areas and helmets for younger riders."}'::jsonb, '{"model_answer": "Although hire e-scooters provide cheap, fast short trips, safety and obstruction concerns have led some cities to introduce parking zones, speed limits and helmet rules."}'::jsonb, 'Use "although" to show the contrast, then give the response.', 'Summarize a problem-solution text in one sentence.', array['Content', 'Form', 'Grammar', 'Vocabulary']::text[], array['cheap fast short trips', 'safety and blocking concerns', 'rules: parking zones, speed limits, helmets']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('2f54806e-1a14-5c38-b358-c020d863578a', 'we-0001', 'cefac6c4-c50a-586c-b734-2ea833cbec6b', 'intermediate', 'You will have 20 minutes to plan, write and revise an essay about the topic below. Your response should be between 200 and 300 words.', '{"prompt": "Some people believe that university education should be free for all students. Others think students should pay part of the cost. Discuss both views and give your own opinion."}'::jsonb, '{"outline": ["Introduction: restate topic and give opinion", "Body 1: arguments for free education", "Body 2: arguments for students paying", "Conclusion: summary and opinion"]}'::jsonb, 'Plan four paragraphs. Support each idea with a reason and an example.', 'Write a balanced discussion essay.', array['Content', 'Form', 'Development, structure and coherence', 'Grammar', 'General linguistic range', 'Vocabulary range', 'Spelling']::text[], array['benefits of free education', 'reasons for student contribution', 'clear personal opinion']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('64a4f1d7-c03e-5d9c-b4bf-9ad233e0b49b', 'we-0002', 'cefac6c4-c50a-586c-b734-2ea833cbec6b', 'advanced', 'You will have 20 minutes to plan, write and revise an essay about the topic below. Your response should be between 200 and 300 words.', '{"prompt": "Working from home has become common in many jobs. Do the advantages of working from home outweigh the disadvantages?"}'::jsonb, '{"outline": ["Introduction: context and position", "Body 1: advantages (time, flexibility)", "Body 2: disadvantages (isolation, communication)", "Conclusion: weighed judgement"]}'::jsonb, 'Make your position clear in the introduction and repeat it in the conclusion.', 'Write an advantages-disadvantages essay with a clear position.', array['Content', 'Form', 'Development, structure and coherence', 'Grammar', 'General linguistic range', 'Vocabulary range', 'Spelling']::text[], array['advantages of remote work', 'disadvantages of remote work', 'clear judgement']::text[], 'published');
insert into public.placement_tests (id, slug, title, version, estimated_minutes, items) values ('05283f5f-0130-56e3-83f6-d86c83815425', 'placement-v1', 'Placement test', 1, 15, '[{"id": "d1-r", "level": 1, "skill": "reading", "type": "single_choice", "passage": "Hi, I am Tom. I am ten years old. I have a dog.", "prompt": "How old is Tom?", "options": ["Eight", "Ten", "Twelve"], "answer": "Ten"}, {"id": "d1-w", "level": 1, "skill": "writing", "type": "single_choice", "prompt": "Choose the correct sentence.", "options": ["She are my sister.", "She is my sister.", "She am my sister."], "answer": "She is my sister."}, {"id": "d1-l", "level": 1, "skill": "listening", "type": "single_choice", "audio_script": "Good morning. My name is Sara and I live in a small house.", "prompt": "Where does Sara live?", "options": ["In a small house", "In a big flat", "In a hotel"], "answer": "In a small house"}, {"id": "d2-r", "level": 2, "skill": "reading", "type": "single_choice", "passage": "The shop opens at nine and closes at six. On Sundays it is closed.", "prompt": "When can you NOT visit the shop?", "options": ["Monday morning", "Saturday afternoon", "Sunday"], "answer": "Sunday"}, {"id": "d2-w", "level": 2, "skill": "writing", "type": "single_choice", "prompt": "Yesterday we ___ to the park.", "options": ["go", "went", "going"], "answer": "went"}, {"id": "d2-l", "level": 2, "skill": "listening", "type": "single_choice", "audio_script": "The train to the city leaves from platform four at half past three.", "prompt": "When does the train leave?", "options": ["3:30", "4:00", "4:30"], "answer": "3:30"}, {"id": "d3-r", "level": 3, "skill": "reading", "type": "single_choice", "passage": "Although the new library is further from the town centre, most students prefer it because it stays open until midnight and has quiet study rooms.", "prompt": "Why do most students prefer the new library?", "options": ["It is closer to the centre", "It has longer opening hours and quiet rooms", "It is cheaper to use"], "answer": "It has longer opening hours and quiet rooms"}, {"id": "d3-w", "level": 3, "skill": "writing", "type": "single_choice", "prompt": "If it ___ tomorrow, we will cancel the trip.", "options": ["rains", "will rain", "rained"], "answer": "rains"}, {"id": "d3-l", "level": 3, "skill": "listening", "type": "single_choice", "audio_script": "I was going to study medicine, but after volunteering at a school I realised that teaching was what I really wanted to do.", "prompt": "What did the speaker decide to do?", "options": ["Study medicine", "Become a teacher", "Work in a hospital"], "answer": "Become a teacher"}, {"id": "d4-r", "level": 4, "skill": "reading", "type": "single_choice", "passage": "Remote work has reduced commuting time for many employees. However, some managers report that spontaneous collaboration has declined, which may slow down the development of new ideas.", "prompt": "What concern do some managers have?", "options": ["Employees commute more", "Fewer unplanned conversations may slow innovation", "Remote work costs more money"], "answer": "Fewer unplanned conversations may slow innovation"}, {"id": "d4-w", "level": 4, "skill": "writing", "type": "single_choice", "prompt": "Choose the best word: The results were ___ with earlier studies.", "options": ["consistent", "constant", "considerate"], "answer": "consistent"}, {"id": "d4-l", "level": 4, "skill": "listening", "type": "single_choice", "audio_script": "While the treatment was effective for most patients, researchers noted that its benefits were smaller among older adults, so further trials are needed for that group.", "prompt": "What do the researchers say is needed?", "options": ["More trials with older adults", "A cheaper treatment", "No further research"], "answer": "More trials with older adults"}, {"id": "d5-r", "level": 5, "skill": "reading", "type": "single_choice", "passage": "The author contends that economic growth alone is an inadequate measure of national progress, since it disregards inequality, environmental degradation and the unpaid work that sustains households.", "prompt": "What is the author''s main argument?", "options": ["Growth should be the only measure of progress", "Growth ignores important aspects of progress", "Unpaid work should be taxed"], "answer": "Growth ignores important aspects of progress"}, {"id": "d5-w", "level": 5, "skill": "writing", "type": "single_choice", "prompt": "Choose the correct sentence.", "options": ["Hardly had we arrived when the meeting started.", "Hardly we had arrived when the meeting started.", "Hardly had we arrived than the meeting started."], "answer": "Hardly had we arrived when the meeting started."}, {"id": "d5-l", "level": 5, "skill": "listening", "type": "single_choice", "audio_script": "Critics of the policy argue that, far from encouraging innovation, the subsidies have mainly benefited established firms that would have invested anyway.", "prompt": "What do critics say about the subsidies?", "options": ["They strongly encouraged new firms", "They mostly helped companies that did not need them", "They were too small to matter"], "answer": "They mostly helped companies that did not need them"}, {"id": "d6-r", "level": 6, "skill": "reading", "type": "single_choice", "passage": "Notwithstanding its methodological elegance, the study''s reliance on self-reported data renders its conclusions about actual behaviour somewhat tentative.", "prompt": "What weakness of the study does the writer point out?", "options": ["Its methods are too complicated", "Participants'' own reports may not match what they really do", "It studied too many people"], "answer": "Participants'' own reports may not match what they really do"}, {"id": "d6-w", "level": 6, "skill": "writing", "type": "single_choice", "prompt": "Choose the most precise word: The committee''s decision was ___, so it could not be challenged later.", "options": ["irrevocable", "irrelevant", "irregular"], "answer": "irrevocable"}, {"id": "d6-l", "level": 6, "skill": "listening", "type": "single_choice", "audio_script": "The archive''s value lies less in any single document than in the way the collection, taken as a whole, reveals shifting attitudes over two centuries.", "prompt": "According to the speaker, why is the archive valuable?", "options": ["One famous document is in it", "The whole collection shows how attitudes changed", "It is two centuries old"], "answer": "The whole collection shows how attitudes changed"}]'::jsonb);
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change) values ('00000000-0000-0000-0000-000000000000', '09e72f04-37e7-59e4-b691-004672efbcd9', 'authenticated', 'authenticated', 'demo.student@example.test', extensions.crypt('DemoStudent-123!', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, '{"display_name": "Demo Student", "age_confirmed": "true", "terms_accepted": "true"}'::jsonb, now(), now(), '', '', '', '');
insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at) values ('48ec3cff-a6ce-5b7b-b644-f4fe865f7601', '09e72f04-37e7-59e4-b691-004672efbcd9', '09e72f04-37e7-59e4-b691-004672efbcd9', '{"sub": "09e72f04-37e7-59e4-b691-004672efbcd9", "email": "demo.student@example.test", "email_verified": true}'::jsonb, 'email', now(), now(), now());
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change) values ('00000000-0000-0000-0000-000000000000', '492a9b78-e2f5-5f88-88f0-c585b74a7f6b', 'authenticated', 'authenticated', 'demo.admin@example.test', extensions.crypt('DemoAdmin-123!', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, '{"display_name": "Demo Admin", "age_confirmed": "true", "terms_accepted": "true"}'::jsonb, now(), now(), '', '', '', '');
insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at) values ('ef5e5e6f-b596-514a-96c5-6a0b89f0476d', '492a9b78-e2f5-5f88-88f0-c585b74a7f6b', '492a9b78-e2f5-5f88-88f0-c585b74a7f6b', '{"sub": "492a9b78-e2f5-5f88-88f0-c585b74a7f6b", "email": "demo.admin@example.test", "email_verified": true}'::jsonb, 'email', now(), now(), now());
insert into public.user_roles (user_id, role) values ('492a9b78-e2f5-5f88-88f0-c585b74a7f6b', 'admin');
